// --- Configuración: ajusta a la disponibilidad real ---
const CALENDAR_EMAIL = 'sofimh1197@gmail.com';
const TIMEZONE = 'America/Mexico_City'; // ajusta si su zona horaria es otra
const WORK_START_HOUR = 9;   // 9:00 am
const WORK_END_HOUR = 18;    // 6:00 pm
const SLOT_MINUTES = 30;
const MIN_NOTICE_HOURS = 4;  // no ofrecer horarios antes de N horas desde ahora
const SEARCH_DAYS = 10;      // buscar en los próximos N días
const MAX_SLOTS = 8;         // cuántas opciones devolver como máximo

// --- Recolectar los períodos ocupados que devolvió el nodo "Disponibilidad" ---
let busy = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j.busy)) {
    busy.push(...j.busy);
  } else if (j.calendars && j.calendars[CALENDAR_EMAIL] && Array.isArray(j.calendars[CALENDAR_EMAIL].busy)) {
    busy.push(...j.calendars[CALENDAR_EMAIL].busy);
  } else if (j.start && j.end) {
    busy.push({ start: j.start, end: j.end });
  }
}
const busyRanges = busy.map((b) => ({
  start: DateTime.fromISO(b.start).toMillis(),
  end: DateTime.fromISO(b.end).toMillis(),
}));

function overlaps(startMs, endMs) {
  return busyRanges.some((b) => startMs < b.end && endMs > b.start);
}

const now = DateTime.now().setZone(TIMEZONE);
const earliest = now.plus({ hours: MIN_NOTICE_HOURS });
const slots = [];

for (let d = 0; d < SEARCH_DAYS && slots.length < MAX_SLOTS; d++) {
  const day = now.plus({ days: d }).startOf('day');
  if (day.weekday === 6 || day.weekday === 7) continue; // fin de semana (Luxon: 6=sábado, 7=domingo)

  for (let hour = WORK_START_HOUR; hour < WORK_END_HOUR && slots.length < MAX_SLOTS; hour++) {
    for (let min = 0; min < 60 && slots.length < MAX_SLOTS; min += SLOT_MINUTES) {
      const slotStart = day.set({ hour, minute: min, second: 0, millisecond: 0 });
      const slotEnd = slotStart.plus({ minutes: SLOT_MINUTES });
      if (slotStart < earliest) continue;
      if (overlaps(slotStart.toMillis(), slotEnd.toMillis())) continue;

      slots.push({
        start: slotStart.toISO(),
        end: slotEnd.toISO(),
        humanLabel: slotStart.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a"),
      });
    }
  }
}

return [{ json: { slots } }];

